INSERT IGNORE INTO gastronomic_trails(slug,title,region,description,estimated_duration_hours,transport_tips,cover_image,is_active,editorial_json,editorial_state,reviewed_at) VALUES('mercados-e-sabores-de-belem','Mercados e sabores de Belém','Belém · centro','Uma manhã para observar ingredientes, conversar com feirantes e escolher uma pausa gastronômica.',3,'Escolha as paradas conforme as áreas abertas e o movimento do dia. Pergunte preços e ingredientes antes de consumir.','/images/para-real/ver-o-peso-960.webp',TRUE,'{"Audience":"Quem visita Belém pela primeira vez e gosta de mercados.","Origin":"Complexo do Ver-o-Peso","Mode":"urban","BeforeYouGo":"Escolha as paradas conforme as áreas abertas e o movimento do dia. Pergunte preços e ingredientes antes de consumir.","Accessibility":"Confirme pisos, degraus, banheiros e apoio necessário diretamente com cada local ou operador. Não há auditoria de acessibilidade deste percurso.","Stops":[{"Name":"Mercado de Peixe do Ver-o-Peso","City":"Belém","Summary":"Observe os ingredientes da região. A pausa para comer é uma escolha pessoal; confirme higiene, ingredientes e atendimento no local.","SourceUrl":"https://agencia.belem.pa.gov.br/belem-tera-11-pontos-de-informacoes-turisticas-em-locais-estrategicos/","SourceName":"Agência Belém"},{"Name":"Solar da Beira","City":"Belém","Summary":"Faça uma pausa para observar o conjunto histórico e buscar orientação turística, se o atendimento estiver disponível.","SourceUrl":"https://agencia.belem.pa.gov.br/belem-tera-11-pontos-de-informacoes-turisticas-em-locais-estrategicos/","SourceName":"Agência Belém"},{"Name":"Feira do Açaí","City":"Belém","Summary":"Conheça a relação da feira com o rio. Consumo e observação do trabalho local devem respeitar moradores e comerciantes.","SourceUrl":"https://publica.ciar.ufg.br/projetos/rosa-kliass/obras/pa-estacao-das-docas.html","SourceName":"UFG · pesquisa de paisagem"}]}','published','2026-10-20 00:00:00');
INSERT IGNORE INTO gastronomic_trails(slug,title,region,description,estimated_duration_hours,transport_tips,cover_image,is_active,editorial_json,editorial_state,reviewed_at) VALUES('cidade-velha-sem-pressa','Cidade Velha, cultura e uma pausa à mesa','Belém · Cidade Velha','Um circuito compacto de referências culturais, com tempo livre para escolher onde comer.',3,'Confirme acesso aos interiores, ingressos e calendário cultural. Este roteiro não promete entrada em museus ou restaurante aberto.','/images/para-real/ver-o-peso-960.webp',TRUE,'{"Audience":"Quem prefere história e pequenas pausas.","Origin":"Complexo Feliz Lusitânia","Mode":"urban","BeforeYouGo":"Confirme acesso aos interiores, ingressos e calendário cultural. Este roteiro não promete entrada em museus ou restaurante aberto.","Accessibility":"Confirme pisos, degraus, banheiros e apoio necessário diretamente com cada local ou operador. Não há auditoria de acessibilidade deste percurso.","Stops":[{"Name":"Forte do Presépio","City":"Belém","Summary":"Comece pela paisagem do núcleo histórico. Verifique quais espaços podem ser visitados na data escolhida.","SourceUrl":"https://agencia.belem.pa.gov.br/belem-tera-11-pontos-de-informacoes-turisticas-em-locais-estrategicos/","SourceName":"Agência Belém"},{"Name":"Casa das Onze Janelas","City":"Belém","Summary":"Reserve uma pausa cultural se houver visitação; a etapa não pressupõe consumo em estabelecimento específico.","SourceUrl":"https://agencia.belem.pa.gov.br/belem-tera-11-pontos-de-informacoes-turisticas-em-locais-estrategicos/","SourceName":"Agência Belém"},{"Name":"Catedral da Sé, Belém","City":"Belém","Summary":"Observe o entorno e respeite celebrações. Depois, escolha uma ficha publicada ou confirme uma opção gastronômica próxima.","SourceUrl":"https://www.fapespa.pa.gov.br/wp-content/uploads/2024/03/Belem.pdf","SourceName":"FAPESPA · perfil municipal"}]}','published','2026-10-20 00:00:00');
INSERT IGNORE INTO gastronomic_trails(slug,title,region,description,estimated_duration_hours,transport_tips,cover_image,is_active,editorial_json,editorial_state,reviewed_at) VALUES('docas-entre-mercado-e-rio','Docas: entre o mercado e o rio','Belém · orla central','Uma proposta curta de paisagem e gastronomia para adaptar ao seu ritmo.',2,'Escolha a ordem conforme o acesso do dia; confirme as condições das calçadas e a oferta gastronômica. Duração não inclui deslocamento até o centro.','/images/para-real/ver-o-peso-960.webp',TRUE,'{"Audience":"Quem tem pouco tempo e quer conhecer a orla central.","Origin":"Estação das Docas","Mode":"urban","BeforeYouGo":"Escolha a ordem conforme o acesso do dia; confirme as condições das calçadas e a oferta gastronômica. Duração não inclui deslocamento até o centro.","Accessibility":"Confirme pisos, degraus, banheiros e apoio necessário diretamente com cada local ou operador. Não há auditoria de acessibilidade deste percurso.","Stops":[{"Name":"Estação das Docas","City":"Belém","Summary":"Conheça os armazéns recuperados e escolha uma pausa gastronômica somente após conferir a oferta e os preços do dia.","SourceUrl":"https://publica.ciar.ufg.br/projetos/rosa-kliass/obras/pa-estacao-das-docas.html","SourceName":"UFG · pesquisa de paisagem"},{"Name":"Escadinha da Praça Pedro Teixeira","City":"Belém","Summary":"Observe a relação da praça com a orla; não use o local como indicação de embarque regular sem confirmação.","SourceUrl":"https://www.agenciapara.com.br/noticia/79792/terminal-hidroviario-de-icoaraci-e-liberado-para-o-cirio-fluvial","SourceName":"Agência Pará"},{"Name":"Ver-o-Peso","City":"Belém","Summary":"Se houver atividade, encerre explorando os ingredientes. Fora do atendimento, mantenha a etapa como observação do conjunto urbano.","SourceUrl":"https://agencia.belem.pa.gov.br/belem-tera-11-pontos-de-informacoes-turisticas-em-locais-estrategicos/","SourceName":"Agência Belém"}]}','published','2026-10-20 00:00:00');
INSERT IGNORE INTO gastronomic_trails(slug,title,region,description,estimated_duration_hours,transport_tips,cover_image,is_active,editorial_json,editorial_state,reviewed_at) VALUES('combu-rio-e-cacau','Combu: rio, cacau e cozinha ribeirinha','Belém · Combu','Combine previamente uma experiência de cacau e uma refeição no Combu, respeitando o tempo do rio.',5,'Agende as visitas e combine embarque e retorno com operador regularizado. Não há tarifa, duração de barco ou cardápio confirmado neste roteiro.','/images/para-real/ver-o-peso-960.webp',TRUE,'{"Audience":"Quem deseja planejar uma experiência ribeirinha com antecedência.","Origin":"Belém: ponto de embarque a confirmar com o operador","Mode":"river","BeforeYouGo":"Agende as visitas e combine embarque e retorno com operador regularizado. Não há tarifa, duração de barco ou cardápio confirmado neste roteiro.","Accessibility":"Confirme pisos, degraus, banheiros e apoio necessário diretamente com cada local ou operador. Não há auditoria de acessibilidade deste percurso.","Stops":[{"Name":"Ilha do Combu","City":"Belém","Summary":"Organize a chegada e o retorno antes de escolher as atividades. Não se trata de trajeto para percorrer a pé entre todos os pontos.","SourceUrl":"https://agencia.belem.pa.gov.br/ilhas-de-belem-descubra-praias-e-trilhas-perto-da-capital/","SourceName":"Agência Belém"},{"Name":"Casa do Chocolate da Dona Nena · Filha do Combu","City":"Belém","Summary":"A publicação do Ministério do Turismo menciona a experiência de cacau. Confirme diretamente se há visita e agendamento na data desejada.","SourceUrl":"https://www.gov.br/turismo/pt-br/acesso-a-informacao/acoes-e-programas/programas-projetos-acoes-obras-e-atividades/programa-nacional-de-turismo-gastronomico/BIMT9TURISMOGASTRONMICO.pdf/@@download/file","SourceName":"Ministério do Turismo"},{"Name":"Saldosa Maloca, Combu","City":"Belém","Summary":"Lugar mencionado na mesma publicação gastronômica. Confirme funcionamento, reserva, acessibilidade e cardápio atual; não é recomendação conferida do portal.","SourceUrl":"https://www.gov.br/turismo/pt-br/acesso-a-informacao/acoes-e-programas/programas-projetos-acoes-obras-e-atividades/programa-nacional-de-turismo-gastronomico/BIMT9TURISMOGASTRONMICO.pdf/@@download/file","SourceName":"Ministério do Turismo"}]}','published','2026-10-20 00:00:00');
INSERT IGNORE INTO gastronomic_trails(slug,title,region,description,estimated_duration_hours,transport_tips,cover_image,is_active,editorial_json,editorial_state,reviewed_at) VALUES('cotijuba-um-dia-de-ilha','Cotijuba: prepare seu dia de ilha','Belém · Cotijuba','Uma proposta de planejamento para combinar paisagem e pausa para comer, sem prometer conexões de barco.',7,'Escolha as atividades conforme o transporte local. A ligação entre pontos da ilha não é apresentada como caminhada contínua. Combine o retorno antes de embarcar.','/images/para-real/ver-o-peso-960.webp',TRUE,'{"Audience":"Quem pode reservar o dia e confirmar o retorno antes de sair.","Origin":"Icoaraci: terminal e operador a confirmar","Mode":"river","BeforeYouGo":"Escolha as atividades conforme o transporte local. A ligação entre pontos da ilha não é apresentada como caminhada contínua. Combine o retorno antes de embarcar.","Accessibility":"Confirme pisos, degraus, banheiros e apoio necessário diretamente com cada local ou operador. Não há auditoria de acessibilidade deste percurso.","Stops":[{"Name":"Terminal Hidroviário de Icoaraci","City":"Belém","Summary":"Consulte o operador para confirmar a ligação disponível para Cotijuba, ponto de desembarque, bagagens e retorno.","SourceUrl":"https://www.agenciapara.com.br/noticia/72491/obras-entregues-em-icoaraci-e-outeiro-impulsionam-mobilidade-turismo-e-geracao-de-renda","SourceName":"Agência Pará"},{"Name":"Ilha de Cotijuba","City":"Belém","Summary":"Ao chegar, escolha com apoio local uma pausa para comer e como seguir até a área de visita. Não há restaurante específico ou prato garantido.","SourceUrl":"https://agencia.belem.pa.gov.br/ilhas-de-belem-descubra-praias-e-trilhas-perto-da-capital/","SourceName":"Agência Belém"},{"Name":"Praia do Vai-Quem-Quer, Cotijuba","City":"Belém","Summary":"Destino citado em fonte estadual. Verifique o acesso local, as condições ambientais e o tempo necessário para voltar; banho não é garantido.","SourceUrl":"https://www.agenciapara.com.br/noticia/50145/agricultores-familiares-da-ilha-de-cotijuba-recebem-car-e-outros-beneficios","SourceName":"Agência Pará"}]}','published','2026-10-20 00:00:00');
INSERT IGNORE INTO gastronomic_trails(slug,title,region,description,estimated_duration_hours,transport_tips,cover_image,is_active,editorial_json,editorial_state,reviewed_at) VALUES('mosqueiro-vila-e-paisagem','Mosqueiro: Vila, sabores e paisagem','Belém · Mosqueiro','Planeje um passeio rodoviário com pausas na Vila e na paisagem de rio.',6,'Acesso rodoviário é distinto de travessia fluvial. Organize o transporte entre Vila e praia. Confira obras, condições de banho e funcionamento no dia.','/images/para-real/ver-o-peso-960.webp',TRUE,'{"Audience":"Quem quer escolher suas pausas, com flexibilidade de transporte.","Origin":"Belém, com acesso rodoviário a Mosqueiro","Mode":"road","BeforeYouGo":"Acesso rodoviário é distinto de travessia fluvial. Organize o transporte entre Vila e praia. Confira obras, condições de banho e funcionamento no dia.","Accessibility":"Confirme pisos, degraus, banheiros e apoio necessário diretamente com cada local ou operador. Não há auditoria de acessibilidade deste percurso.","Stops":[{"Name":"Mercado Municipal de Mosqueiro","City":"Belém","Summary":"Observe o mercado e pergunte sobre ingredientes e atendimento. Interdições ou obras podem alterar o percurso.","SourceUrl":"https://agencia.belem.pa.gov.br/orla-mercado-e-praias-obras-da-prefeitura-avancam-em-mosqueiro/","SourceName":"Agência Belém"},{"Name":"Tapiocaria da Vila, Mosqueiro","City":"Belém","Summary":"A referência municipal cita a tradição da tapiocaria. Escolha no local e confirme ingredientes, valores e condições de atendimento.","SourceUrl":"https://agencia.belem.pa.gov.br/uma-homenagem-pelo-olhar-de-quem-mora-e-faz-historia-na-ilha/","SourceName":"Agência Belém"},{"Name":"Praia do Chapéu Virado, Mosqueiro","City":"Belém","Summary":"Reserve uma pausa de paisagem; consulte o boletim ambiental vigente antes de considerar banho. A etapa não inclui promessa de balneabilidade.","SourceUrl":"https://agencia.belem.pa.gov.br/ilhas-de-belem-descubra-praias-e-trilhas-perto-da-capital/","SourceName":"Agência Belém"}]}','published','2026-10-20 00:00:00');
INSERT IGNORE INTO gastronomic_trails(slug,title,region,description,estimated_duration_hours,transport_tips,cover_image,is_active,editorial_json,editorial_state,reviewed_at) VALUES('icoaraci-barro-e-rio','Icoaraci: barro, memória e rio','Belém · Icoaraci','Uma proposta cultural para conhecer a cerâmica e escolher uma pausa gastronômica sem pressa.',4,'A reportagem estadual de julho de 2026 registrava obras na Orla do Cruzeiro. Confirme acessos e considere transporte entre as paradas; visitas às oficinas precisam ser combinadas.','/images/para-real/ver-o-peso-960.webp',TRUE,'{"Audience":"Quem gosta de artesanato e quer conversar com produtores locais.","Origin":"Bairro do Paracuri, Icoaraci","Mode":"road","BeforeYouGo":"A reportagem estadual de julho de 2026 registrava obras na Orla do Cruzeiro. Confirme acessos e considere transporte entre as paradas; visitas às oficinas precisam ser combinadas.","Accessibility":"Confirme pisos, degraus, banheiros e apoio necessário diretamente com cada local ou operador. Não há auditoria de acessibilidade deste percurso.","Stops":[{"Name":"Paracuri, Icoaraci","City":"Belém","Summary":"Procure uma oficina com visita autorizada e valorize o trabalho artesanal. Não há agendamento automático de olaria.","SourceUrl":"https://diariodopara.com.br/encartes/na-estrada-com-o-diario/ceramicas-de-icoaraci-dao-charme-a-vila-sorriso/","SourceName":"Diário do Pará · referência editorial"},{"Name":"Biblioteca Municipal Avertano Rocha, Icoaraci","City":"Belém","Summary":"A referência editorial identifica o antigo chalé como etapa cultural. Confirme abertura e possibilidade de visita.","SourceUrl":"https://diariodopara.com.br/encartes/na-estrada-com-o-diario/ceramicas-de-icoaraci-dao-charme-a-vila-sorriso/","SourceName":"Diário do Pará · referência editorial"},{"Name":"Orla do Cruzeiro, Icoaraci","City":"Belém","Summary":"Escolha somente trechos com acesso permitido. Confirme obras e oferta gastronômica antes de reservar uma pausa.","SourceUrl":"https://agenciapara.com.br/noticia/78844/obra-da-nova-orla-do-cruzeiro-avanca-no-distrito-de-icoaraci-em-belem","SourceName":"Agência Pará"}]}','published','2026-10-20 00:00:00');
