-- Editorial content is inserted once; administrator edits are never overwritten by a read or rerun.
ALTER TABLE gastronomic_trails ADD COLUMN editorial_json LONGTEXT NULL, ADD COLUMN editorial_state VARCHAR(20) NOT NULL DEFAULT 'legacy', ADD COLUMN reviewed_at DATETIME(6) NULL, ADD COLUMN editorial_version INT NOT NULL DEFAULT 1;
CREATE TABLE editorial_trail_revisions(id BIGINT AUTO_INCREMENT PRIMARY KEY, trail_id INT UNSIGNED NOT NULL, version INT NOT NULL, snapshot_json LONGTEXT NOT NULL, actor VARCHAR(160) NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), KEY ix_trail_revision(trail_id,version), CONSTRAINT fk_editorial_revision FOREIGN KEY(trail_id) REFERENCES gastronomic_trails(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE editorial_review_queue(id BIGINT AUTO_INCREMENT PRIMARY KEY, trail_id INT UNSIGNED NOT NULL, version INT NOT NULL, state VARCHAR(20) NOT NULL DEFAULT 'pending', created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), UNIQUE KEY ux_editorial_review(trail_id,version), CONSTRAINT fk_editorial_review FOREIGN KEY(trail_id) REFERENCES gastronomic_trails(id) ON DELETE CASCADE) ENGINE=InnoDB;
